#!/usr/bin/env python3
import hashlib,json,re,subprocess,sys
from pathlib import Path
d=Path(__file__).resolve().parents[2];p=d/'research/nine-seed38-jones-dependent07-staged-check'
def h(q):return hashlib.sha256(q.read_bytes()).hexdigest()
for n,v in {'run.py':'4ac8dae43dad506a25bec3a60fa3fe7c1939b223498f7791a1551cdbf198fb88','provider_preflight.py':'86cdaeb2d6480b5a1609067f2457e66062387fe5b59a7e605e3c1bbd3753e15b','source-manifest.json':'b82279f85c9cee0159a5857a083c5fc239ac5ef03fd1b528e822ffcc1359a77d'}.items():assert h(p/n)==v
rows=json.loads((p/'source-manifest.json').read_text())['rows'];expected=[('Norm38MacroDependentI','716b1b31e873561f9490e903d6e4f7b2b24b89d0958d54ea2fea15abd57519c7','Norm38MacroDependentH',['d34_Gprime_carry','prefix_I']),('Norm38MacroDependentA0Early','8a0a39e304e5321c1bc3e33f3299462792c4d6ac57943b8b769fad9dc243943d','Norm38MacroDependentI',['d28_P_carry','d29_K_carry']),('Norm38MacroDependentA0','f481670fd4ea6c06b102b6c43d65b67116ee98d077687f5ccc92760ff789087f','Norm38MacroDependentA0Early',['d35_P_carry','d35_K_carry','prefix_A0']),('Norm38MacroDependentA1','2e1fff89404888e30e2c4ac01f9a52220612b83b7b1231292fd37d0713e1456c','Norm38MacroDependentA0',['d36_D_carry','d36_F_carry','d36_I_carry','prefix_A1']),('Norm38MacroDependentV','d39cbafb286d71e7e98c5d5b56d97fd08081d53dfcf2b7d2da08b781c0f858f5','Norm38MacroDependentA1',['d37_A0_carry','d38_A1_carry','prefix_V0','prefix_V1'])];assert len(rows)==5
for row,(n,sha,imp,ts) in zip(rows,expected):
 q=p/'src/DiophantineConsistency'/f'{n}.lean';assert h(q)==sha==row['source_sha256'];s=q.read_text();assert row['module']=='DiophantineConsistency.'+n;assert row['imports']==re.findall(r'^import ([\w.]+)$',s,re.M)==['DiophantineConsistency.'+imp];assert re.findall(r'^theorem (\w+)',s,re.M)==ts and re.findall(r'^#print axioms (\w+)',s,re.M)==ts
 for a,b,c in re.findall(r'd(\d+)\.values a \(\(Fin\.last (\d+)\)((?:\.castSucc)*)\)',s):assert int(a)==int(b)+1+c.count('.castSucc')
i=(p/'src/DiophantineConsistency/Norm38MacroDependentI.lean').read_text();a0=(p/'src/DiophantineConsistency/Norm38MacroDependentA0.lean').read_text();a1=(p/'src/DiophantineConsistency/Norm38MacroDependentA1.lean').read_text();v=(p/'src/DiophantineConsistency/Norm38MacroDependentV.lean').read_text()
for source,checks in [(i,['d34.values a ⟨32, by decide⟩) ^ (2 : Nat)','d34.values a ⟨33, by decide⟩) ^ (2 : Nat)']), (a0,['d35.values a ⟨21, by decide⟩) ^ (2 : Nat)','d35.values a ⟨22, by decide⟩) ^ (2 : Nat)']), (a1,['d36.values a ⟨29, by decide⟩ *','d36.values a ⟨31, by decide⟩ * d36.values a ⟨34, by decide⟩']), (v,['d37.values a ⟨35, by decide⟩) ^ (2 : Nat) + ((2 : Int) : R)','d38.values a ⟨36, by decide⟩) ^ (2 : Nat) + ((2 : Int) : R)'])]:assert all(x in source for x in checks)
named=(d/'research/nine-seed38-jones-named-prefix-draft/Norm38MacroPrefixes.lean').read_text();lines=named.splitlines();expected_nodes=['def d35 : Dag 35 := .snoc d34 (.add (.mul (.sub (.pow (.ref ⟨32, by decide⟩) (.lit 2)) (.constant (1 : Int))) (.pow (.ref ⟨33, by decide⟩) (.lit 2))) (.constant (1 : Int)))','def d36 : Dag 36 := .snoc d35 (.add (.mul (.sub (.pow (.ref ⟨21, by decide⟩) (.lit 2)) (.constant (1 : Int))) (.pow (.ref ⟨22, by decide⟩) (.lit 2))) (.constant (1 : Int)))','def d37 : Dag 37 := .snoc d36 (.mul (.mul (.ref ⟨29, by decide⟩) (.ref ⟨31, by decide⟩)) (.ref ⟨34, by decide⟩))','def d38 : Dag 38 := .snoc d37 (.add (.pow (.ref ⟨35, by decide⟩) (.lit 2)) (.constant (2 : Int)))','def d39 : Dag 39 := .snoc d38 (.add (.pow (.ref ⟨36, by decide⟩) (.lit 2)) (.constant (2 : Int)))'];assert all(x in lines for x in expected_nodes)
r=subprocess.run([sys.executable,'-I','-S','-B',str(p/'run.py'),'--preflight'],capture_output=True,text=True,check=True);o=json.loads(r.stdout);assert o['status']=='PASS_NO_LEAN_PREFLIGHT' and o['stage_count']==5
print(json.dumps({'status':'PASS','preflight':o,'scope':'uncompiled I/A0/A1/V prefix evaluations; no Lean replay'},sort_keys=True,indent=2))
